package cf_math_pkg;

    // Ceil division of integers
    function automatic integer ceil_div(integer dividend, integer divisor);
        return (dividend + divisor - 1) / divisor;
    endfunction

    // Floor division of integers
    function automatic integer floor_div(integer dividend, integer divisor);
        return dividend / divisor;
    endfunction

    // Binary logarithm of integer
    function automatic integer log2(integer value);
        integer result;
        result = 0;
        while (value > 1) begin
            value = value >> 1;
            result++;
        end
        return result;
    endfunction

endpackage

