module gray_to_binary #(
    parameter int N = 1
)(
    input  logic [N-1:0] A,
    output logic [N-1:0] Z
);
    always_comb begin
        Z = A;
        for (int i = 1; i < N; i++) begin
            Z = Z ^ (Z << 1);
        end
    end
endmodule

