package ecc_pkg;

    function automatic int get_parity_width(int data_width);
        int parity_width = 2;
        while ((1 << parity_width) < (data_width + parity_width + 1)) parity_width++;
        return parity_width;
    endfunction

    function automatic int get_cw_width(int data_width);
        return data_width + get_parity_width(data_width) + 1;
    endfunction

endpackage

