module ecc_encode #(
    parameter int unsigned DataWidth = 64,
    localparam int unsigned ParityWidth = ecc_pkg::get_parity_width(DataWidth),
    localparam int unsigned CodewordWidth = DataWidth + ParityWidth + 1
)(
    input  logic [DataWidth-1:0]    data_i,
    output logic [CodewordWidth-1:0] data_o
);
    logic [CodewordWidth-1:0] codeword;

    always_comb begin
        int unsigned idx;
        // Place data bits in non-power-of-2 positions
        idx = 0;
        for (int i = 1; i <= CodewordWidth - 1; i++) begin
            if (!((i & (i - 1)) == 0)) begin // not power of 2
                codeword[i-1] = data_i[idx];
                idx++;
            end else begin
                codeword[i-1] = 1'b0;
            end
        end

        // Calculate parity bits
        for (int i = 0; i < ParityWidth; i++) begin
            logic parity;
            parity = 1'b0;
            for (int j = 1; j <= CodewordWidth - 1; j++) begin
                if (j[i]) begin
                    parity ^= codeword[j-1];
                end
            end
            codeword[(1 << i) - 1] = parity;
        end

        // Overall parity bit (last bit)
        codeword[CodewordWidth-1] = 1'b0;
        for (int i = 0; i < CodewordWidth - 1; i++) begin
            codeword[CodewordWidth-1] ^= codeword[i];
        end
    end

    assign data_o = codeword;
endmodule

