module onehot_to_bin #(
    parameter int unsigned ONEHOT_WIDTH = 1,
    parameter int unsigned BIN_WIDTH    = (ONEHOT_WIDTH > 32'd1) ? $clog2(ONEHOT_WIDTH) : 32'd1
)(
    input  logic [ONEHOT_WIDTH-1:0] onehot_i,
    output logic [BIN_WIDTH-1:0]    bin_o
);
    always_comb begin
        bin_o = '0;
        for (int unsigned i = 0; i < ONEHOT_WIDTH; i++) begin
            if (onehot_i[i]) begin
                bin_o = BIN_WIDTH'(i);
            end
        end
    end
endmodule

