module cc_onehot #(
    parameter int unsigned WIDTH = 1
)(
    input  logic [WIDTH-1:0] d_i,
    output logic [WIDTH-1:0] q_o
);
    always_comb begin
        q_o = '0;
        for (int i = 0; i < WIDTH; i++) begin
            if (d_i[i]) begin
                q_o[i] = 1'b1;
                break;
            end
        end
    end
endmodule

