module lzc #(
    parameter int unsigned WIDTH = 1,
    parameter bit          MODE  = 1'b0, // 0 = leading zero, 1 = trailing zero
    parameter bit          CNT_WIDTH = (WIDTH > 1) ? $clog2(WIDTH) : 1
)(
    input  logic [WIDTH-1:0]     in_i,
    output logic [CNT_WIDTH-1:0] cnt_o,
    output logic                 empty_o
);
    logic [WIDTH-1:0] reversed;
    logic [WIDTH-1:0] vector;

    // Reverse if trailing zero count
    always_comb begin
        for (int i = 0; i < WIDTH; i++) begin
            reversed[i] = in_i[WIDTH-1-i];
        end
    end

    assign vector = MODE ? reversed : in_i;

    // Leading zero count using priority encoder
    always_comb begin
        cnt_o = '0;
        empty_o = ~|vector;
        for (int i = WIDTH-1; i >= 0; i--) begin
            if (vector[i]) begin
                cnt_o = CNT_WIDTH'(WIDTH-1-i);
            end
        end
    end
endmodule

