module fifo_v3 #(
    parameter bit          FALL_THROUGH = 1'b0,
    parameter int unsigned DATA_WIDTH   = 32,
    parameter int unsigned DEPTH        = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic flush_i,
    input  logic testmode_i,
    output logic full_o,
    output logic empty_o,
    output logic [$clog2(DEPTH+1)-1:0] usage_o,
    input  logic [DATA_WIDTH-1:0] data_i,
    input  logic push_i,
    output logic [DATA_WIDTH-1:0] data_o,
    input  logic pop_i
);
    localparam int unsigned ADDR_DEPTH = (DEPTH > 1) ? $clog2(DEPTH) : 1;

    logic [ADDR_DEPTH-1:0] read_pointer_n, read_pointer_q;
    logic [ADDR_DEPTH-1:0] write_pointer_n, write_pointer_q;
    logic [ADDR_DEPTH:0] status_cnt_n, status_cnt_q;
    logic [DATA_WIDTH-1:0] mem_n[DEPTH];
    logic [DATA_WIDTH-1:0] mem_q[DEPTH];

    assign usage_o = status_cnt_q;
    assign full_o  = (status_cnt_q == DEPTH);
    assign empty_o = (status_cnt_q == 0) & ~(FALL_THROUGH & push_i);

    // Read and write pointers
    always_comb begin
        read_pointer_n  = read_pointer_q;
        write_pointer_n = write_pointer_q;
        status_cnt_n    = status_cnt_q;

        if (flush_i) begin
            read_pointer_n  = '0;
            write_pointer_n = '0;
            status_cnt_n    = '0;
        end else begin
            if (push_i && !full_o) begin
                write_pointer_n = write_pointer_q + 1;
                status_cnt_n    = status_cnt_q + 1;
            end
            if (pop_i && !empty_o) begin
                read_pointer_n = read_pointer_q + 1;
                status_cnt_n   = status_cnt_q - 1;
            end
            // If both push and pop in same cycle
            if (push_i && !full_o && pop_i && !empty_o) begin
                status_cnt_n = status_cnt_q;
            end
        end
    end

    // Memory update
    always_comb begin
        mem_n = mem_q;
        if (push_i && !full_o) begin
            mem_n[write_pointer_q] = data_i;
        end
    end

    // Output data
    if (FALL_THROUGH) begin : gen_fall_through
        assign data_o = (status_cnt_q == 0) ? data_i : mem_q[read_pointer_q];
    end else begin : gen_no_fall_through
        assign data_o = mem_q[read_pointer_q];
    end

    `FF(read_pointer_q, read_pointer_n, '0)
    `FF(write_pointer_q, write_pointer_n, '0)
    `FF(status_cnt_q, status_cnt_n, '0)

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            for (int i = 0; i < DEPTH; i++) begin
                mem_q[i] <= '0;
            end
        end else begin
            mem_q <= mem_n;
        end
    end
endmodule

