module counter #(
    parameter int unsigned WIDTH = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic clear_i,
    input  logic en_i,
    input  logic load_i,
    input  logic down_i,
    input  logic [WIDTH-1:0] d_i,
    output logic [WIDTH-1:0] q_o,
    output logic overflow_o
);
    logic [WIDTH-1:0] counter_d, counter_q;

    always_comb begin
        counter_d = counter_q;
        overflow_o = 1'b0;

        if (clear_i) begin
            counter_d = '0;
        end else if (load_i) begin
            counter_d = d_i;
        end else if (en_i) begin
            if (down_i) begin
                counter_d = counter_q - 1;
                overflow_o = (counter_q == '0);
            end else begin
                counter_d = counter_q + 1;
                overflow_o = (counter_q == {WIDTH{1'b1}});
            end
        end
    end

    `FF(counter_q, counter_d, '0)
    assign q_o = counter_q;
endmodule

// Copyright 2018 ETH Zurich and University of Bologna.
