module credit_counter #(
    parameter int unsigned WIDTH = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic clear_i,
    input  logic en_i,
    input  logic credit_i,
    input  logic debit_i,
    output logic [WIDTH-1:0] q_o,
    output logic full_o,
    output logic empty_o
);
    logic [WIDTH-1:0] counter_d, counter_q;

    always_comb begin
        counter_d = counter_q;

        if (clear_i) begin
            counter_d = '0;
        end else if (en_i) begin
            if (credit_i && !debit_i) begin
                counter_d = counter_q + 1;
            end else if (!credit_i && debit_i) begin
                counter_d = counter_q - 1;
            end else if (credit_i && debit_i) begin
                counter_d = counter_q;
            end
        end
    end

    `FF(counter_q, counter_d, '0)
    assign q_o = counter_q;
    assign full_o  = (counter_q == {WIDTH{1'b1}});
    assign empty_o = (counter_q == '0);
endmodule

