module boxcar #(
    parameter int unsigned WIDTH = 32
)(
    input  logic [WIDTH-1:0] data_i,
    output logic [WIDTH-1:0] data_o
);
    always_comb begin
        data_o = '0;
        for (int i = 0; i < WIDTH; i++) begin
            if (data_i[i]) begin
                data_o[i] = 1'b1;
            end else if (i > 0 && data_o[i-1]) begin
                data_o[i] = 1'b1;
            end else begin
                data_o[i] = 1'b0;
            end
        end
    end
endmodule

