module rr_arb_tree #(
    parameter int unsigned NumInp   = 32'd1,
    parameter int unsigned DataWidth = 32'd1,
    parameter bit          ExtPrio  = 1'b0,
    parameter bit          AxiVldRdy = 1'b0,
    parameter bit          LockIn   = 1'b0,
    parameter bit          FairArb  = 1'b1
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic flush_i,
    input  logic [$clog2(NumInp)-1:0] rr_i,
    input  logic [NumInp-1:0] req_i,
    output logic [NumInp-1:0] gnt_o,
    input  logic [NumInp-1:0][DataWidth-1:0] data_i,
    input  logic gnt_i,
    output logic req_o,
    output logic [DataWidth-1:0] data_o,
    output logic [$clog2(NumInp)-1:0] idx_o
);
    localparam int unsigned IdxWidth = (NumInp > 1) ? $clog2(NumInp) : 1;

    logic [NumInp-1:0] req_d;
    logic [NumInp-1:0] req_mask;
    logic [NumInp-1:0] req_masked;
    logic [NumInp-1:0] gnt;
    logic [IdxWidth-1:0] idx;
    logic no_req;

    // Round robin logic
    logic [IdxWidth-1:0] rr_q;
    logic [NumInp-1:0] req_tmp;

    always_comb begin
        req_d = req_i;
        if (LockIn) begin
            if (req_o && gnt_i) begin
                req_d = req_i & ~gnt_o;
            end else if (req_o) begin
                req_d = req_i & gnt_o;
            end
        end
    end

    // Generate mask
    always_comb begin
        req_mask = '0;
        for (int i = 0; i < NumInp; i++) begin
            if (i >= rr_q) begin
                req_mask[i] = 1'b1;
            end
        end
    end

    assign req_masked = req_d & req_mask;
    assign req_tmp = (req_masked != '0) ? req_masked : req_d;

    // Priority encoder
    always_comb begin
        gnt = '0;
        idx = '0;
        for (int i = NumInp - 1; i >= 0; i--) begin
            if (req_tmp[i]) begin
                gnt = '0;
                gnt[i] = 1'b1;
                idx = IdxWidth'(i);
            end
        end
    end

    assign no_req = ~|req_d;
    assign req_o = |req_d;
    assign gnt_o = gnt;
    assign idx_o = idx;

    // Data output
    always_comb begin
        data_o = '0;
        for (int i = 0; i < NumInp; i++) begin
            if (gnt[i]) begin
                data_o = data_i[i];
            end
        end
    end

    // Round robin pointer update
    `include "common_cells/registers.svh"
    `FF(rr_q, ((req_o && gnt_i) || !FairArb) ? idx + 1 : rr_q, '0)
endmodule

