module spill_register #(
    parameter type T = logic
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic valid_i,
    output logic ready_o,
    input  T data_i,
    output logic valid_o,
    input  logic ready_i,
    output T data_o
);
    logic valid_q;
    T data_q;
    logic full;

    `include "common_cells/registers.svh"

    assign full = valid_q;
    assign ready_o = ~full;

    always_comb begin
        valid_o = valid_i || valid_q;
        if (valid_q) begin
            data_o = data_q;
        end else begin
            data_o = data_i;
        end
    end

    `FFL(valid_q, valid_i, ready_o && valid_i && ~ready_i, 1'b0)
    `FFL(data_q, data_i, ready_o && valid_i && ~ready_i, '0)
endmodule

