module fall_through_register #(
    parameter type T = logic
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic valid_i,
    output logic ready_o,
    input  T data_i,
    output logic valid_o,
    input  logic ready_i,
    output T data_o
);
    logic valid_q;
    T data_q;

    `include "common_cells/registers.svh"

    assign ready_o = ~valid_q || ready_i;
    assign valid_o = valid_q || valid_i;
    assign data_o  = valid_q ? data_q : data_i;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            valid_q <= 1'b0;
            data_q  <= '0;
        end else begin
            if (ready_o) begin
                valid_q <= valid_i;
                if (valid_i) begin
                    data_q <= data_i;
                end
            end
        end
    end
endmodule

