module passthrough_stream_fifo #(
    parameter int unsigned DATA_WIDTH = 32,
    parameter int unsigned DEPTH      = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic flush_i,
    input  logic testmode_i,
    output logic full_o,
    output logic empty_o,
    output logic [$clog2(DEPTH+1)-1:0] usage_o,
    input  logic [DATA_WIDTH-1:0] data_i,
    input  logic valid_i,
    output logic ready_o,
    output logic [DATA_WIDTH-1:0] data_o,
    output logic valid_o,
    input  logic ready_i
);
    logic [DATA_WIDTH-1:0] mem[DEPTH];
    logic [$clog2(DEPTH+1)-1:0] count_q, count_d;
    logic [$clog2(DEPTH)-1:0] rd_ptr_q, rd_ptr_d;
    logic [$clog2(DEPTH)-1:0] wr_ptr_q, wr_ptr_d;
    logic push, pop;

    `include "common_cells/registers.svh"

    assign push = valid_i && ready_o;
    assign pop  = valid_o && ready_i;
    assign full_o  = (count_q == DEPTH);
    assign empty_o = (count_q == 0);
    assign usage_o = count_q;

    always_comb begin
        rd_ptr_d = rd_ptr_q;
        wr_ptr_d = wr_ptr_q;
        count_d  = count_q;

        if (flush_i) begin
            rd_ptr_d = '0;
            wr_ptr_d = '0;
            count_d  = '0;
        end else begin
            if (push && !full_o) begin
                wr_ptr_d = wr_ptr_q + 1;
                count_d  = count_q + 1;
            end
            if (pop && !empty_o) begin
                rd_ptr_d = rd_ptr_q + 1;
                count_d  = count_q - 1;
            end
            if (push && !full_o && pop && !empty_o) begin
                count_d = count_q;
            end
        end
    end

    assign data_o = (count_q == 0) ? data_i : mem[rd_ptr_q];
    assign valid_o = valid_i || (count_q > 0);
    assign ready_o = ~full_o || (count_q > 0 && ready_i);

    `FF(rd_ptr_q, rd_ptr_d, '0)
    `FF(wr_ptr_q, wr_ptr_d, '0)
    `FF(count_q, count_d, '0)

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            for (int i = 0; i < DEPTH; i++) begin
                mem[i] <= '0;
            end
        end else begin
            if (push && !full_o) begin
                mem[wr_ptr_q] <= data_i;
            end
        end
    end
endmodule

