module cdc_2phase_dst #(
    parameter type T = logic
)(
    input  logic rst_ni,
    input  logic clk_i,
    output T     data_o,
    output logic valid_o,
    input  logic ready_i,
    input  logic async_req_i,
    output logic async_ack_o,
    input  T     async_data_i
);
    logic req_q, ack_q;
    T data_q;
    `include "common_cells/registers.svh"

    assign valid_o = req_q ^ ack_q;
    assign data_o = data_q;
    assign async_ack_o = ack_q;

    `FF(req_q, async_req_i, 1'b0)
    `FF(ack_q, valid_o && ready_i ? ~ack_q : ack_q, 1'b0)

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            data_q <= '0;
        end else if (req_q ^ ack_q) begin
            data_q <= async_data_i;
        end
    end
endmodule

