module cdc_4phase #(
    parameter type T = logic
)(
    input  logic src_rst_ni,
    input  logic src_clk_i,
    input  T     src_data_i,
    input  logic src_valid_i,
    output logic src_ready_o,

    input  logic dst_rst_ni,
    input  logic dst_clk_i,
    output T     dst_data_o,
    output logic dst_valid_o,
    input  logic dst_ready_i
);
    logic async_req, async_ack;
    T async_data;

    // Source domain
    logic src_req_q;
    T src_data_q;
    `include "common_cells/registers.svh"

    assign src_ready_o = ~src_req_q;

    always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
        if (!src_rst_ni) begin
            src_req_q <= 1'b0;
            src_data_q <= '0;
        end else begin
            if (src_valid_i && src_ready_o) begin
                src_req_q <= 1'b1;
                src_data_q <= src_data_i;
            end else if (src_req_q && async_ack) begin
                src_req_q <= 1'b0;
            end
        end
    end

    assign async_req = src_req_q;
    assign async_data = src_data_q;

    // Destination domain
    logic dst_req_q, dst_ack_q;
    T dst_data_q;

    sync #(.STAGES(2)) i_sync_req (
        .clk_i    (dst_clk_i),
        .rst_ni   (dst_rst_ni),
        .serial_i (async_req),
        .serial_o (dst_req_q)
    );

    sync #(.STAGES(2)) i_sync_ack (
        .clk_i    (src_clk_i),
        .rst_ni   (src_rst_ni),
        .serial_i (dst_ack_q),
        .serial_o (async_ack)
    );

    assign dst_valid_o = dst_req_q && ~dst_ack_q;
    assign dst_data_o = dst_data_q;

    always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
        if (!dst_rst_ni) begin
            dst_ack_q <= 1'b0;
            dst_data_q <= '0;
        end else begin
            if (dst_valid_o && dst_ready_i) begin
                dst_ack_q <= 1'b1;
            end else if (~dst_req_q) begin
                dst_ack_q <= 1'b0;
            end
            if (dst_valid_o && dst_ready_i) begin
                dst_data_q <= async_data;
            end
        end
    end
endmodule

