module cdc_fifo_2phase #(
    parameter type T = logic,
    parameter int unsigned DEPTH = 8
)(
    input  logic src_rst_ni,
    input  logic src_clk_i,
    input  T     src_data_i,
    input  logic src_valid_i,
    output logic src_ready_o,

    input  logic dst_rst_ni,
    input  logic dst_clk_i,
    output T     dst_data_o,
    output logic dst_valid_o,
    input  logic dst_ready_i
);
    logic [DEPTH-1:0][T.width-1:0] mem;
    logic [$clog2(DEPTH)-1:0] src_wptr, dst_rptr;
    logic src_req, dst_ack;
    logic [$clog2(DEPTH+1)-1:0] src_cnt, dst_cnt;

    // Simplified implementation
    assign src_ready_o = (src_cnt < DEPTH);
    assign dst_valid_o = (dst_cnt > 0);
    assign dst_data_o = mem[dst_rptr];

    `include "common_cells/registers.svh"

    always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
        if (!src_rst_ni) begin
            src_wptr <= '0;
            src_cnt <= '0;
        end else begin
            if (src_valid_i && src_ready_o) begin
                mem[src_wptr] <= src_data_i;
                src_wptr <= src_wptr + 1;
                src_cnt <= src_cnt + 1;
            end
        end
    end

    always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
        if (!dst_rst_ni) begin
            dst_rptr <= '0;
            dst_cnt <= '0;
        end else begin
            if (dst_valid_o && dst_ready_i) begin
                dst_rptr <= dst_rptr + 1;
                dst_cnt <= dst_cnt - 1;
            end
        end
    end
endmodule

