module cdc_fifo_gray #(
    parameter type T = logic,
    parameter int unsigned DEPTH = 8
)(
    input  logic src_rst_ni,
    input  logic src_clk_i,
    input  T     src_data_i,
    input  logic src_valid_i,
    output logic src_ready_o,

    input  logic dst_rst_ni,
    input  logic dst_clk_i,
    output T     dst_data_o,
    output logic dst_valid_o,
    input  logic dst_ready_i
);
    localparam int unsigned ADDR_WIDTH = (DEPTH > 1) ? $clog2(DEPTH) : 1;

    logic [ADDR_WIDTH:0] src_wptr_bin, src_wptr_gray;
    logic [ADDR_WIDTH:0] dst_rptr_bin, dst_rptr_gray;
    logic [ADDR_WIDTH:0] src_rptr_gray_sync, dst_wptr_gray_sync;
    logic [DEPTH-1:0][T.width-1:0] mem;

    `include "common_cells/registers.svh"

    // Source domain
    assign src_ready_o = (src_wptr_gray != {~dst_wptr_gray_sync[ADDR_WIDTH:ADDR_WIDTH-1], dst_wptr_gray_sync[ADDR_WIDTH-2:0]});

    always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
        if (!src_rst_ni) begin
            src_wptr_bin <= '0;
            src_wptr_gray <= '0;
        end else begin
            if (src_valid_i && src_ready_o) begin
                mem[src_wptr_bin[ADDR_WIDTH-1:0]] <= src_data_i;
                src_wptr_bin <= src_wptr_bin + 1;
                src_wptr_gray <= (src_wptr_bin + 1) ^ ((src_wptr_bin + 1) >> 1);
            end
        end
    end

    // Destination domain
    assign dst_valid_o = (dst_rptr_gray != dst_wptr_gray_sync);
    assign dst_data_o = mem[dst_rptr_bin[ADDR_WIDTH-1:0]];

    always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
        if (!dst_rst_ni) begin
            dst_rptr_bin <= '0;
            dst_rptr_gray <= '0;
        end else begin
            if (dst_valid_o && dst_ready_i) begin
                dst_rptr_bin <= dst_rptr_bin + 1;
                dst_rptr_gray <= (dst_rptr_bin + 1) ^ ((dst_rptr_bin + 1) >> 1);
            end
        end
    end

    // Sync pointers
    sync #(.STAGES(2)) i_sync_wptr [ADDR_WIDTH:0] (
        .clk_i    (dst_clk_i),
        .rst_ni   (dst_rst_ni),
        .serial_i (src_wptr_gray),
        .serial_o (dst_wptr_gray_sync)
    );

    sync #(.STAGES(2)) i_sync_rptr [ADDR_WIDTH:0] (
        .clk_i    (src_clk_i),
        .rst_ni   (src_rst_ni),
        .serial_i (dst_rptr_gray),
        .serial_o (src_rptr_gray_sync)
    );
endmodule

