module clk_int_div #(
    parameter int unsigned DIV_VALUE_WIDTH = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic en_i,
    input  logic test_mode_en_i,
    input  logic [DIV_VALUE_WIDTH-1:0] div_i,
    input  logic div_valid_i,
    output logic div_ready_o,
    output logic clk_o,
    output logic [DIV_VALUE_WIDTH-1:0] cycl_count_o
);
    logic [DIV_VALUE_WIDTH-1:0] div_q;
    logic [DIV_VALUE_WIDTH-1:0] cnt_q;
    logic clk_q;
    logic div_valid_q;

    `include "common_cells/registers.svh"

    assign div_ready_o = 1'b1;
    assign cycl_count_o = cnt_q;
    assign clk_o = test_mode_en_i ? clk_i : clk_q;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            div_q <= '0;
            cnt_q <= '0;
            clk_q <= 1'b0;
            div_valid_q <= 1'b0;
        end else begin
            if (div_valid_i && div_ready_o) begin
                div_q <= div_i;
                div_valid_q <= 1'b1;
            end
            if (en_i) begin
                if (cnt_q >= div_q - 1 || div_q == 0) begin
                    cnt_q <= '0;
                    clk_q <= ~clk_q;
                end else begin
                    cnt_q <= cnt_q + 1;
                end
            end else begin
                cnt_q <= '0;
                clk_q <= 1'b0;
            end
        end
    end
endmodule

