module clk_int_div_static #(
    parameter int unsigned DIV_VALUE = 2,
    parameter bit ENABLE_CLOCK_IN_RESET = 1'b0
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic en_i,
    input  logic test_mode_en_i,
    output logic clk_o
);
    localparam int unsigned DIV_VALUE_WIDTH = $clog2(DIV_VALUE);

    logic [DIV_VALUE_WIDTH-1:0] cnt_q;
    logic clk_q;
    `include "common_cells/registers.svh"

    assign clk_o = test_mode_en_i ? clk_i : clk_q;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            cnt_q <= '0;
            clk_q <= ENABLE_CLOCK_IN_RESET ? 1'b0 : 1'b0;
        end else begin
            if (en_i) begin
                if (cnt_q >= DIV_VALUE - 1) begin
                    cnt_q <= '0;
                    clk_q <= ~clk_q;
                end else begin
                    cnt_q <= cnt_q + 1;
                end
            end else begin
                cnt_q <= '0;
                clk_q <= 1'b0;
            end
        end
    end
endmodule

