module clk_mux_glitch_free #(
    parameter int unsigned N_INPUTS = 2
)(
    input  logic [N_INPUTS-1:0] clks_i,
    input  logic [$clog2(N_INPUTS)-1:0] sel_i,
    input  logic rst_ni,
    output logic clk_o
);
    logic [N_INPUTS-1:0] sel_q;
    logic [N_INPUTS-1:0] en;
    logic [N_INPUTS-1:0] clk_gated;

    `include "common_cells/registers.svh"

    always_comb begin
        en = '0;
        en[sel_i] = 1'b1;
    end

    `FF(sel_q, en, '0)

    assign clk_o = |clk_gated;

    genvar i;
    generate
        for (i = 0; i < N_INPUTS; i++) begin : gen_clk_gate
            assign clk_gated[i] = clks_i[i] & sel_q[i];
        end
    endgenerate
endmodule

