module addr_decode #(
    parameter int unsigned NoIndices = 1,
    parameter int unsigned NoRules   = 1,
    parameter type addr_t = logic,
    parameter type rule_t = logic
)(
    input  addr_t addr_i,
    input  rule_t [NoRules-1:0] addr_map_i,
    output logic [$clog2(NoIndices)-1:0] idx_o,
    output logic dec_valid_o,
    output logic dec_error_o,
    input  logic en_default_idx_i,
    input  logic [$clog2(NoIndices)-1:0] default_idx_i
);
    always_comb begin
        dec_valid_o = 1'b0;
        dec_error_o = 1'b1;
        idx_o = default_idx_i;
        for (int i = NoRules - 1; i >= 0; i--) begin
            if (addr_i >= addr_map_i[i].start_addr && addr_i < addr_map_i[i].end_addr) begin
                idx_o = addr_map_i[i].idx[$clog2(NoIndices)-1:0];
                dec_valid_o = 1'b1;
                dec_error_o = 1'b0;
            end
        end
        if (!dec_valid_o && en_default_idx_i) begin
            dec_error_o = 1'b0;
        end
    end
endmodule

