module multiaddr_decode #(
    parameter int unsigned NoIndices = 1,
    parameter int unsigned NoRules   = 1,
    parameter type addr_t = logic,
    parameter type rule_t = logic
)(
    input  addr_t [1:0] addr_i,
    input  rule_t [NoRules-1:0] addr_map_i,
    output logic [1:0][$clog2(NoIndices)-1:0] idx_o,
    output logic [1:0] dec_valid_o,
    output logic [1:0] dec_error_o,
    input  logic [1:0] en_default_idx_i,
    input  logic [1:0][$clog2(NoIndices)-1:0] default_idx_i
