    genvar i;
    generate
        for (i = 0; i < 2; i++) begin : gen_decode
            addr_decode_napot #(
                .NoIndices (NoIndices),
                .NoRules   (NoRules),
                .addr_t    (addr_t),
                .rule_t    (rule_t)
            ) i_decode (
                .addr_i           (addr_i[i]),
                .addr_map_i       (addr_map_i),
                .idx_o            (idx_o[i]),
                .dec_valid_o      (dec_valid_o[i]),
                .dec_error_o      (dec_error_o[i]),
                .en_default_idx_i (en_default_idx_i[i]),
                .default_idx_i    (default_idx_i[i])
            );
        end
    endgenerate
