module lfsr #(
    parameter int unsigned WIDTH = 64,
    parameter logic [WIDTH-1:0] SEED = 64'h1,
    parameter bit WHITEEN = 1'b0
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic en_i,
    output logic [WIDTH-1:0] out_o
);
    logic [WIDTH-1:0] lfsr_q;
    logic feedback;
    `include "common_cells/registers.svh"

    // Galois LFSR with primitive polynomial for common widths
    always_comb begin
        feedback = lfsr_q[WIDTH-1];
        case (WIDTH)
            4:  feedback = lfsr_q[3] ^ lfsr_q[0];
            8:  feedback = lfsr_q[7] ^ lfsr_q[5] ^ lfsr_q[4] ^ lfsr_q[3];
            16: feedback = lfsr_q[15] ^ lfsr_q[13] ^ lfsr_q[12] ^ lfsr_q[10];
            32: feedback = lfsr_q[31] ^ lfsr_q[21] ^ lfsr_q[1] ^ lfsr_q[0];
            64: feedback = lfsr_q[63] ^ lfsr_q[61] ^ lfsr_q[60] ^ lfsr_q[59];
            default: feedback = lfsr_q[WIDTH-1] ^ lfsr_q[0];
        endcase
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            lfsr_q <= SEED;
        end else if (en_i) begin
            lfsr_q <= {lfsr_q[WIDTH-2:0], feedback};
        end
    end

    assign out_o = WHITEEN ? lfsr_q ^ (lfsr_q >> 1) : lfsr_q;
endmodule

