module plru_tree #(
    parameter int unsigned ENTRIES = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic [$clog2(ENTRIES)-1:0] used_i,
    input  logic used_valid_i,
    output logic [$clog2(ENTRIES)-1:0] plru_o
);
    localparam int unsigned LEVELS = $clog2(ENTRIES);
    logic [ENTRIES-2:0] tree_q, tree_d;
    `include "common_cells/registers.svh"

    always_comb begin
        tree_d = tree_q;
        if (used_valid_i) begin
            int unsigned node;
            node = 0;
            for (int i = LEVELS - 1; i >= 0; i--) begin
                tree_d[node] = ~used_i[i];
                if (used_i[i]) begin
                    node = 2 * node + 2;
                end else begin
                    node = 2 * node + 1;
                end
            end
        end
    end

    always_comb begin
        int unsigned node;
        node = 0;
        plru_o = '0;
        for (int i = LEVELS - 1; i >= 0; i--) begin
            plru_o[i] = tree_q[node];
            if (tree_q[node]) begin
                node = 2 * node + 2;
            end else begin
                node = 2 * node + 1;
            end
        end
    end

    `FF(tree_q, tree_d, '0)
endmodule

