module id_queue #(
    parameter int unsigned ID_WIDTH = 4,
    parameter int unsigned CAPACITY = 8,
    parameter type data_t = logic
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic [ID_WIDTH-1:0] push_id_i,
    input  data_t push_data_i,
    input  logic push_i,
    output logic full_o,
    input  logic [ID_WIDTH-1:0] pop_id_i,
    output data_t pop_data_o,
    output logic pop_valid_o,
    input  logic pop_i,
    input  logic [ID_WIDTH-1:0] exists_id_i,
    output logic exists_o
);
    logic [CAPACITY-1:0][ID_WIDTH-1:0] ids_q;
    logic [CAPACITY-1:0] valid_q;
    data_t [CAPACITY-1:0] data_q;
    logic [$clog2(CAPACITY)-1:0] free_idx;
    logic free_found;
    `include "common_cells/registers.svh"

    always_comb begin
        free_found = 1'b0;
        free_idx = '0;
        for (int i = 0; i < CAPACITY; i++) begin
            if (!valid_q[i] && !free_found) begin
                free_found = 1'b1;
                free_idx = i;
            end
        end
    end

    assign full_o = &valid_q;
    assign pop_valid_o = valid_q[pop_id_i];
    assign pop_data_o = data_q[pop_id_i];
    assign exists_o = valid_q[exists_id_i];

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            valid_q <= '0;
        end else begin
            if (push_i && !full_o) begin
                valid_q[free_idx] <= 1'b1;
                ids_q[free_idx] <= push_id_i;
                data_q[free_idx] <= push_data_i;
            end
            if (pop_i && pop_valid_o) begin
                valid_q[pop_id_i] <= 1'b0;
            end
        end
    end
endmodule

