module stream_xbar #(
    parameter int unsigned NumInp = 2,
    parameter int unsigned NumOut = 2,
    parameter type payload_t = logic,
    parameter bit SpillReg = 1'b0
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic flush_i,
    input  payload_t [NumInp-1:0] data_i,
    input  logic [$clog2(NumOut)-1:0] [NumInp-1:0] sel_i,
    input  logic [NumInp-1:0] valid_i,
    output logic [NumInp-1:0] ready_o,
    output payload_t [NumOut-1:0] data_o,
    output logic [NumOut-1:0] valid_o,
    input  logic [NumOut-1:0] ready_i
);
    // Simple crossbar implementation
    for (genvar j = 0; j < NumOut; j++) begin : gen_out
        logic [NumInp-1:0] req;
        payload_t [NumInp-1:0] data;
        logic [NumInp-1:0] gnt;
        logic [$clog2(NumInp)-1:0] idx;

        for (genvar i = 0; i < NumInp; i++) begin : gen_in
            assign req[i] = valid_i[i] && (sel_i[i] == j);
            assign data[i] = data_i[i];
        end

        rr_arb_tree #(
            .NumIn     (NumInp),
            .DataWidth ($bits(payload_t)),
            .ExtPrio   (1'b0),
            .AxiVldRdy (1'b1),
            .LockIn    (1'b1)
        ) i_arb (
            .clk_i   (clk_i),
            .rst_ni  (rst_ni),
            .flush_i (flush_i),
            .rr_i    ('0),
            .req_i   (req),
            .gnt_o   (gnt),
            .data_i  (data),
            .gnt_i   (ready_i[j]),
            .req_o   (valid_o[j]),
            .data_o  (data_o[j]),
            .idx_o   (idx)
        );

        for (genvar i = 0; i < NumInp; i++) begin : gen_ready
            assign ready_o[i] = gnt[i] && (sel_i[i] == j);
        end
    end
endmodule

