module stream_delay #(
    parameter int unsigned FIXED_DELAY = 0,
    parameter int unsigned MAX_DELAY = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic valid_i,
    output logic ready_o,
    input  logic [31:0] data_i,
    output logic valid_o,
    input  logic ready_i,
    output logic [31:0] data_o
);
    logic [$clog2(MAX_DELAY+1)-1:0] delay_cnt;
    logic [MAX_DELAY-1:0][31:0] shift_reg;
    `include "common_cells/registers.svh"

    assign ready_o = ready_i;
    assign data_o = shift_reg[MAX_DELAY-1];
    assign valid_o = valid_i && (delay_cnt >= FIXED_DELAY);

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            delay_cnt <= '0;
            shift_reg <= '0;
        end else begin
            if (valid_i && ready_o) begin
                shift_reg <= {shift_reg[MAX_DELAY-2:0], data_i};
                if (delay_cnt < FIXED_DELAY) begin
                    delay_cnt <= delay_cnt + 1;
                end
            end
        end
    end
endmodule

