module spill_register_flushable #(
    parameter type T = logic
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic flush_i,
    input  logic valid_i,
    output logic ready_o,
    input  T data_i,
    output logic valid_o,
    input  logic ready_i,
    output T data_o
);
    logic valid_q;
    T data_q;
    `include "common_cells/registers.svh"

    assign ready_o = ~valid_q || ready_i;
    assign valid_o = valid_q && ~flush_i;
    assign data_o = data_q;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            valid_q <= 1'b0;
            data_q <= '0;
        end else begin
            if (flush_i) begin
                valid_q <= 1'b0;
            end else if (ready_o && valid_i) begin
                valid_q <= 1'b1;
                data_q <= data_i;
            end else if (ready_i && valid_q) begin
                valid_q <= 1'b0;
            end
        end
    end
endmodule

