module stream_fifo_optimal_wrap #(
    parameter int unsigned DATA_WIDTH = 32,
    parameter int unsigned DEPTH = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic flush_i,
    input  logic testmode_i,
    output logic full_o,
    output logic empty_o,
    output logic usage_o,
    input  logic [DATA_WIDTH-1:0] data_i,
    input  logic valid_i,
    output logic ready_o,
    output logic [DATA_WIDTH-1:0] data_o,
    output logic valid_o,
    input  logic ready_i
);
    generate
        if (DEPTH == 0) begin : gen_pass_through
            assign ready_o = ready_i;
            assign valid_o = valid_i;
            assign data_o = data_i;
            assign full_o = 1'b0;
            assign empty_o = ~valid_i;
            assign usage_o = 1'b0;
        end else if (DEPTH == 1) begin : gen_spill_reg
            spill_register #(
                .T(logic [DATA_WIDTH-1:0])
            ) i_spill (
                .clk_i   (clk_i),
                .rst_ni  (rst_ni),
                .valid_i (valid_i),
                .ready_o (ready_o),
                .data_i  (data_i),
                .valid_o (valid_o),
                .ready_i (ready_i),
                .data_o  (data_o)
            );
            assign full_o = valid_o && ~ready_i;
            assign empty_o = ~valid_o;
            assign usage_o = valid_o;
        end else begin : gen_fifo
            stream_fifo #(
                .DATA_WIDTH(DATA_WIDTH),
                .DEPTH(DEPTH)
            ) i_fifo (
                .clk_i   (clk_i),
                .rst_ni  (rst_ni),
                .flush_i (flush_i),
                .testmode_i(testmode_i),
                .full_o  (full_o),
                .empty_o (empty_o),
                .usage_o (usage_o),
                .data_i  (data_i),
                .valid_i (valid_i),
                .ready_o (ready_o),
                .data_o  (data_o),
                .valid_o (valid_o),
                .ready_i (ready_i)
            );
        end
    endgenerate
endmodule

