module cb_filter #(
    parameter int unsigned KHashes = 3,
    parameter int unsigned HashWidth = 6,
    parameter int unsigned HashRounds = 1,
    parameter int unsigned InpWidth = 11,
    parameter int unsigned BucketWidth = 3,
    parameter cb_filter_pkg::cb_seed_t [KHashes-1:0] Seeds = '0
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic [InpWidth-1:0] look_data_i,
    output logic look_valid_o,
    input  logic [InpWidth-1:0] incr_data_i,
    input  logic incr_valid_i,
    input  logic [InpWidth-1:0] decr_data_i,
    input  logic decr_valid_i,
    input  logic filter_clear_i,
    output logic [HashWidth-1:0] filter_usage_o,
    output logic filter_full_o,
    output logic filter_empty_o,
    output logic filter_error_o
);
    localparam int unsigned NUM_BUCKETS = 2**HashWidth;
    logic [NUM_BUCKETS-1:0][BucketWidth-1:0] buckets;
    logic [KHashes-1:0][HashWidth-1:0] hashes;
    logic [BucketWidth-1:0] min_count;

    `include "common_cells/registers.svh"

    // Hash functions
    for (genvar i = 0; i < KHashes; i++) begin : gen_hash
        sub_per_hash #(
            .InpWidth   (InpWidth),
            .HashWidth  (HashWidth),
            .NoRounds   (HashRounds),
            .PermuteKey (Seeds[i].PermuteSeed),
            .XorKey     (Seeds[i].XorSeed)
        ) i_hash (
            .data_i        (look_data_i),
            .hash_o        (hashes[i]),
            .hash_onehot_o ()
        );
    end

    // Lookup
    always_comb begin
        min_count = {BucketWidth{1'b1}};
        for (int i = 0; i < KHashes; i++) begin
            if (buckets[hashes[i]] < min_count) begin
                min_count = buckets[hashes[i]];
            end
        end
    end
    assign look_valid_o = (min_count > 0);

    // Update buckets
    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            for (int i = 0; i < NUM_BUCKETS; i++) begin
                buckets[i] <= '0;
            end
        end else begin
            if (filter_clear_i) begin
                for (int i = 0; i < NUM_BUCKETS; i++) begin
                    buckets[i] <= '0;
                end
            end else begin
                if (incr_valid_i) begin
                    for (int i = 0; i < KHashes; i++) begin
                        if (buckets[hashes[i]] < {BucketWidth{1'b1}}) begin
                            buckets[hashes[i]] <= buckets[hashes[i]] + 1;
                        end
                    end
                end
                if (decr_valid_i) begin
                    for (int i = 0; i < KHashes; i++) begin
                        if (buckets[hashes[i]] > 0) begin
                            buckets[hashes[i]] <= buckets[hashes[i]] - 1;
                        end
                    end
                end
            end
        end
    end

    assign filter_full_o = 1'b0;
    assign filter_empty_o = 1'b0;
    assign filter_error_o = 1'b0;
    assign filter_usage_o = '0;
endmodule

