module sub_per_hash #(
    parameter int unsigned InpWidth = 11,
    parameter int unsigned HashWidth = 5,
    parameter int unsigned NoRounds = 1,
    parameter int unsigned PermuteKey = 32'h299034753,
    parameter int unsigned XorKey = 32'h4094834
)(
    input  logic [InpWidth-1:0] data_i,
    output logic [HashWidth-1:0] hash_o,
    output logic [2**HashWidth-1:0] hash_onehot_o
);
    logic [InpWidth-1:0] data;
    logic [HashWidth-1:0] hash;

    always_comb begin
        data = data_i;
        for (int r = 0; r < NoRounds; r++) begin
            data = data ^ PermuteKey[InpWidth-1:0];
            data = {data[InpWidth-2:0], data[InpWidth-1]};
        end
        hash = data[HashWidth-1:0] ^ XorKey[HashWidth-1:0];
    end

    assign hash_o = hash;
    assign hash_onehot_o = 1 << hash;
endmodule

