module clock_divider_counter #(
    parameter int unsigned DIV_VALUE = 2
)(
    input  logic clk_i,
    input  logic rst_ni,
    output logic clk_o
);
    logic [$clog2(DIV_VALUE)-1:0] cnt_q;
    logic clk_q;
    `include "common_cells/registers.svh"

    assign clk_o = clk_q;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            cnt_q <= '0;
            clk_q <= 1'b0;
        end else begin
            if (cnt_q >= DIV_VALUE - 1) begin
                cnt_q <= '0;
                clk_q <= ~clk_q;
            end else begin
                cnt_q <= cnt_q + 1;
            end
        end
    end
endmodule

