    input  logic [NumIn-1:0] req_i,
    output logic [NumIn-1:0] gnt_o,
    input  logic [NumIn-1:0][DataWidth-1:0] data_i,
    input  logic gnt_i,
    output logic req_o,
    output logic [DataWidth-1:0] data_o,
    output logic [$clog2(NumIn)-1:0] idx_o
);
    localparam int unsigned IdxWidth = (NumIn > 1) ? $clog2(NumIn) : 1;

    logic [NumIn-1:0] req_d;
    logic [NumIn-1:0] req_mask;
    logic [NumIn-1:0] req_masked;
    logic [NumIn-1:0] gnt;
    logic [IdxWidth-1:0] idx;
    logic no_req;

    // Round robin logic
    logic [IdxWidth-1:0] rr_q;
    logic [NumIn-1:0] req_tmp;

    always_comb begin
        req_d = req_i;
        if (LockIn) begin
            if (req_o && gnt_i) begin
                req_d = req_i & ~gnt_o;
            end else if (req_o) begin
                req_d = req_i & gnt_o;
            end
        end
    end

    // Generate mask
    always_comb begin
        req_mask = '0;
        for (int i = 0; i < NumIn; i++) begin
            if (i >= rr_q) begin
                req_mask[i] = 1'b1;
            end
        end
    end

    assign req_masked = req_d & req_mask;
    assign req_tmp = (req_masked != '0) ? req_masked : req_d;

    // Priority encoder
    always_comb begin
        gnt = '0;
        idx = '0;
        for (int i = NumIn - 1; i >= 0; i--) begin
            if (req_tmp[i]) begin
                gnt = '0;
                gnt[i] = 1'b1;
                idx = IdxWidth'(i);
            end
        end
    end

