module clk_mux_glitch_free #(
    parameter int unsigned NUM_INPUTS = 2
)(
    input  logic [NUM_INPUTS-1:0] clks_i,
    input  logic test_clk_i,
    input  logic test_en_i,
    input  logic async_rstn_i,
    input  logic [$clog2(NUM_INPUTS)-1:0] async_sel_i,
    output logic clk_o
);
    logic [NUM_INPUTS-1:0] sel_q;
    logic [NUM_INPUTS-1:0] en;
    logic [NUM_INPUTS-1:0] clk_gated;

    always_comb begin
        en = '0;
        en[async_sel_i] = 1'b1;
    end

    always_ff @(posedge test_clk_i or negedge async_rstn_i) begin
        if (!async_rstn_i) begin
            sel_q <= '0;
        end else begin
            sel_q <= en;
        end
    end

    assign clk_o = |clk_gated;

    genvar i;
    generate
        for (i = 0; i < NUM_INPUTS; i++) begin : gen_clk_gate
            assign clk_gated[i] = clks_i[i] & sel_q[i];
        end
    endgenerate
endmodule

