module generic_fifo_adv #(
    parameter int unsigned DATA_WIDTH = 32,
    parameter int unsigned DEPTH = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic [DATA_WIDTH-1:0] data_i,
    input  logic push_i,
    output logic [DATA_WIDTH-1:0] data_o,
    input  logic pop_i,
    output logic full_o,
    output logic empty_o
);
    fifo_v3 #(
        .FALL_THROUGH(1'b0),
        .DATA_WIDTH(DATA_WIDTH),
        .DEPTH(DEPTH)
    ) i_fifo (
        .clk_i   (clk_i),
        .rst_ni  (rst_ni),
        .flush_i (1'b0),
        .testmode_i(1'b0),
        .full_o  (full_o),
        .empty_o (empty_o),
        .usage_o (),
        .data_i  (data_i),
        .push_i  (push_i),
        .data_o  (data_o),
        .pop_i   (pop_i)
    );
endmodule
